'use strict';
var stream = require('readable-stream');
var Readable = require('readable-stream').Readable;
var Transform = require('readable-stream/transform');
var PassThrough = require('readable-stream/passthrough.js');
var Writable = require('readable-stream/writable');
var Duplex = require('readable-stream/duplex');
var LibPassThrough = require('readable-stream/lib/_stream_passthrough.js');

exports.shout = function (words, done) {
  const source = new Readable({ read: function () {} });
  const upper = new stream.Transform({
    transform: function (chunk, encoding, callback) {
      callback(null, String(chunk).toUpperCase());
    }
  });
  var seen = [];
  const sink = new Writable({
    write: function (chunk, encoding, callback) {
      seen.push(String(chunk));
      callback();
    }
  });
  sink.on('finish', function () {
    done(seen.join('|'));
  });
  source.pipe(new PassThrough()).pipe(upper).pipe(new LibPassThrough()).pipe(sink);
  words.forEach(function (w) {
    source.push(w);
  });
  source.push(null);
};

exports.kinds = function () {
  var d = new Duplex({
    read: function () {
      this.push('duplex');
      this.push(null);
    },
    write: function (chunk, encoding, callback) {
      callback();
    }
  });
  d.setEncoding('utf8');
  return typeof stream.Readable + ',' + typeof stream.Stream + ',' + typeof Transform + ',' + typeof d;
};
